//       <Particles />
//       <SectionContainer>
//         <h2 className="text-4xl font-bold text-primary dark:text-accent mb-12 text-center">Core Technical Skills</h2>
//         <div className="flex flex-wrap justify-center gap-4">
//           {skills.map((skill, idx) => (
//             <motion.div
//               key={idx}
//               className="px-4 py-2 bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-white rounded-lg shadow hover:scale-105 transform transition"
//               initial={{ opacity: 0, y: 20 }}
//               whileInView={{ opacity: 1, y: 0 }}
//               viewport={{ once: true }}
//               transition={{ delay: idx * 0.05 }}
//             >
//               {skill}
//             </motion.div>
//           ))}
//         </div>
//       </SectionContainer>
//     </section>
//   );
// };




const Skills = () => {
  const skills = [
    // Backend & APIs
    "Laravel",
    "Symfony",
    "PHP 8+",
    "MVC",
    "OOP",
    "SOLID",
    "DDD",
    "Event-Driven Architecture",
    "REST APIs",
    "OAuth",
    "JWT",
    "Node.js",
    "Python",

    // Frontend
    "React",
    "Vue.js",
    "Blade",
    "Livewire",
    "Tailwind CSS",
    "JavaScript",
    "TypeScript",
    "Vite",

    // Mobile
    "React Native",
    "Android/iOS Integration",
    "Uber APIs",

    // Databases & Data
    "MySQL",
    "MariaDB",
    "PostgreSQL",
    "MongoDB",
    "Schema Design",
    "Indexing",
    "Query Profiling",
    "Data Modeling",
    "ETL",

    // Infrastructure & DevOps
    "AWS (EC2, S3, SQS, RDS)",
    "Google Cloud Platform (GCP)",
    "Microsoft Azure",
    "Docker",
    "Redis",
    "Laravel Forge",
    "Firebase",
    "Apache",
    "Ubuntu Linux",
    "Debian Linux",
    "Linux",
    "Bash",
    "PowerShell",
    "Command Prompt",
    "Shell Scripting",
    "CI/CD",
    "GitHub Actions",

    // Testing & Quality
    "PHPUnit",
    "Pest",
    "Integration Testing",
    "End-to-End Testing",
    "Vitest",
    "Jest",
    "Cypress",
    "PSR Standards",
    "Code Reviews",
    "Git",

    // Support & Operations
    "Application Support (L1 & L2)",
    "ITIL",
    "System Configuration",
    "Troubleshooting",
    "Microsoft 365",
    "MS Office",

    // WordPress
    "WordPress",
    "Plugin Development",
    "Theme Customization",
    "REST API (WP)",
    "Gutenberg",
